"""
Polynomial and Calculus Helper Module

Provides polynomial arithmetic, evaluation, differentiation, integration,
root finding by Newton-Raphson and bisection methods, and pretty printing.
"""

from typing import List, Tuple, Optional, Callable

class Polynomial:
    """
    Represents a polynomial with coefficients in ascending order of powers.
    For example, coefficients [1, 2, 3] represents 1 + 2x + 3x^2.
    """

    def __init__(self, coeffs: List[float]):
        self.coeffs = self._remove_trailing_zeros(coeffs)

    def _remove_trailing_zeros(self, coeffs: List[float]) -> List[float]:
        """Remove trailing zeros from coefficients list."""
        res = coeffs[:]
        while len(res) > 1 and abs(res[-1]) < 1e-14:
            res.pop()
        return res

    def degree(self) -> int:
        """Returns the degree of the polynomial."""
        return len(self.coeffs) - 1

    def __repr__(self) -> str:
        """Pretty print the polynomial."""
        terms = []
        for power, coeff in enumerate(self.coeffs):
            if abs(coeff) < 1e-14:
                continue
            coeff_str = f'{abs(coeff):g}' if abs(coeff) != 1 or power == 0 else ''
            if power == 0:
                term = f'{coeff:g}'
            elif power == 1:
                term = f'{coeff_str}x'
